CREATE TABLE menu_categories (
                                 id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
                                 restaurant_id UUID NOT NULL REFERENCES restaurants(id) ON DELETE CASCADE,
                                 name VARCHAR(100) NOT NULL,
                                 display_order INTEGER DEFAULT 0,
                                 icon_url VARCHAR(255),
                                 is_active BOOLEAN DEFAULT TRUE,
                                 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
                                 updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
                                 deleted_at TIMESTAMP
);

CREATE INDEX idx_menu_categories_restaurant ON menu_categories(restaurant_id);
CREATE INDEX idx_menu_categories_display_order ON menu_categories(display_order);

ALTER TABLE menu_items ADD COLUMN search_vector tsvector;
CREATE INDEX idx_menu_items_search ON menu_items USING GIN(search_vector);

CREATE OR REPLACE FUNCTION menu_items_search_trigger() RETURNS trigger AS $$
BEGIN
    NEW.search_vector :=
        setweight(to_tsvector('english', COALESCE(NEW.name, '')), 'A') ||
        setweight(to_tsvector('english', COALESCE(NEW.description, '')), 'B') ||
        setweight(to_tsvector('english', COALESCE(NEW.ingredients, '')), 'C');
RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER menu_items_search_update
    BEFORE INSERT OR UPDATE OF name, description, ingredients
                     ON menu_items
                         FOR EACH ROW
                         EXECUTE FUNCTION menu_items_search_trigger();

CREATE TABLE qr_scans (
                          id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
                          restaurant_id UUID NOT NULL REFERENCES restaurants(id) ON DELETE CASCADE,
                          ip_address VARCHAR(45),
                          user_agent TEXT,
                          device_type VARCHAR(50),
                          scan_location GEOGRAPHY(Point, 4326),
                          scanned_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_qr_scans_restaurant ON qr_scans(restaurant_id);
CREATE INDEX idx_qr_scans_date ON qr_scans(scanned_at);

CREATE TABLE search_history (
                                id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
                                search_query VARCHAR(255) NOT NULL,
                                search_type VARCHAR(20),
                                restaurant_id UUID REFERENCES restaurants(id) ON DELETE SET NULL,
                                results_count INTEGER DEFAULT 0,
                                ip_address VARCHAR(45),
                                user_location GEOGRAPHY(Point, 4326),
                                searched_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_search_history_query ON search_history(search_query);
CREATE INDEX idx_search_history_date ON search_history(searched_at);
CREATE INDEX idx_search_history_restaurant ON search_history(restaurant_id);
